-- CRBAS database schema (SQLite). Applied automatically on first start
-- when university_booking.db does not exist yet. One statement per line.
CREATE TABLE User ( userID TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('Staff','Student','Admin')), maxActiveBookings INTEGER NOT NULL DEFAULT 3 CHECK(maxActiveBookings > 0), password TEXT NOT NULL DEFAULT 'changeme', firstName TEXT NOT NULL DEFAULT '', lastName TEXT NOT NULL DEFAULT '', createdDate TEXT, createdTime TEXT);
CREATE TABLE Staff ( userID TEXT PRIMARY KEY REFERENCES User(userID) ON DELETE CASCADE, staffID TEXT NOT NULL UNIQUE, jobTitle TEXT NOT NULL, department TEXT NOT NULL );
CREATE TABLE Student ( userID TEXT PRIMARY KEY REFERENCES User(userID) ON DELETE CASCADE, studentID TEXT NOT NULL UNIQUE, course TEXT NOT NULL, yearOfStudy INTEGER NOT NULL CHECK(yearOfStudy BETWEEN 1 AND 7), enrolledAt TEXT NOT NULL DEFAULT (date('now')) );
CREATE TABLE Admin ( userID TEXT PRIMARY KEY REFERENCES User(userID) ON DELETE CASCADE, adminLevel INTEGER NOT NULL DEFAULT 1 CHECK(adminLevel BETWEEN 1 AND 3) );
CREATE TABLE Resource ( resourceID TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('StudyRoom','Equipment','Lab')), requiredRole TEXT NOT NULL DEFAULT 'Student' CHECK(requiredRole IN ('Student','Staff','Admin')), maxBookingDuration INTEGER NOT NULL DEFAULT 120 CHECK(maxBookingDuration > 0), isActive INTEGER NOT NULL DEFAULT 1 CHECK(isActive IN (0,1)), building TEXT, room TEXT);
CREATE TABLE StudyRoom ( resourceID TEXT PRIMARY KEY REFERENCES Resource(resourceID) ON DELETE CASCADE, capacity INTEGER NOT NULL CHECK(capacity > 0), hasProjector INTEGER NOT NULL DEFAULT 0 CHECK(hasProjector IN (0,1)), hasWhiteboard INTEGER NOT NULL DEFAULT 0 CHECK(hasWhiteboard IN (0,1)) );
CREATE TABLE Equipment ( resourceID TEXT PRIMARY KEY REFERENCES Resource(resourceID) ON DELETE CASCADE, quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity > 0), equipmentType TEXT NOT NULL, serialNumber TEXT, isPortable INTEGER NOT NULL DEFAULT 0 CHECK(isPortable IN (0,1)) );
CREATE TABLE Lab ( resourceID TEXT PRIMARY KEY REFERENCES Resource(resourceID) ON DELETE CASCADE, labType TEXT NOT NULL, safetyLevel INTEGER NOT NULL DEFAULT 1 CHECK(safetyLevel BETWEEN 1 AND 5), maxOccupancy INTEGER NOT NULL DEFAULT 10 CHECK(maxOccupancy > 0), supervisorRequired INTEGER NOT NULL DEFAULT 0 CHECK(supervisorRequired IN (0,1)) );
CREATE TABLE MaintenanceWindow ( id INTEGER PRIMARY KEY AUTOINCREMENT, resourceID TEXT NOT NULL REFERENCES Resource(resourceID) ON DELETE CASCADE, reason TEXT , startDate TEXT, startTime TEXT, endDate TEXT, endTime TEXT);
CREATE TABLE Booking ( bookingID TEXT PRIMARY KEY, userID TEXT NOT NULL REFERENCES User(userID) ON DELETE RESTRICT, resourceID TEXT NOT NULL REFERENCES Resource(resourceID) ON DELETE RESTRICT, startTime TEXT NOT NULL, endTime TEXT NOT NULL, date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','cancelled','completed')), quantityBooked INTEGER NOT NULL DEFAULT 1 CHECK(quantityBooked >= 1), attendeeCount INTEGER NOT NULL DEFAULT 1 CHECK(attendeeCount >= 1), cancelledBy TEXT REFERENCES User(userID), createdDate TEXT, createdTime TEXT, updatedDate TEXT, updatedTime TEXT, cancelledDate TEXT, cancelledTime TEXT);
CREATE TABLE BookingHistory ( id INTEGER PRIMARY KEY AUTOINCREMENT, bookingID TEXT NOT NULL REFERENCES Booking(bookingID) ON DELETE CASCADE, changedBy TEXT NOT NULL REFERENCES User(userID), oldStart TEXT, oldEnd TEXT, oldDate TEXT, oldStatus TEXT, newStart TEXT, newEnd TEXT, newDate TEXT, newStatus TEXT, changedDate TEXT, changedTime TEXT);
CREATE TABLE BookingConflictChecker ( id INTEGER PRIMARY KEY AUTOINCREMENT, resourceID TEXT NOT NULL REFERENCES Resource(resourceID) ON DELETE CASCADE, bookingID TEXT REFERENCES Booking(bookingID) ON DELETE SET NULL, requestedStart TEXT NOT NULL, requestedEnd TEXT NOT NULL, hasConflict INTEGER NOT NULL DEFAULT 0 CHECK(hasConflict IN (0,1)), conflictReason TEXT, checkedDate TEXT, checkedTime TEXT);
CREATE INDEX idx_booking_userID ON Booking(userID);
CREATE INDEX idx_booking_resourceID ON Booking(resourceID);
CREATE INDEX idx_booking_status ON Booking(status);
CREATE INDEX idx_booking_date ON Booking(date);
CREATE INDEX idx_booking_resource_date ON Booking(resourceID, date);
CREATE INDEX idx_maintenance_resourceID ON MaintenanceWindow(resourceID);
CREATE INDEX idx_bookinghistory_bookingID ON BookingHistory(bookingID);
